<!doctype html>
<html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Marketing Workspace V2 · Enterprise BPM</title><style>
:root{font-family:Inter,-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;color:#162d49;background:#f2f5fa;font-size:14px}*{box-sizing:border-box}body{margin:0}button,input,textarea,select{font:inherit}button{cursor:pointer}button:disabled{opacity:.5;cursor:not-allowed}aside{position:fixed;inset:0 auto 0 0;width:244px;background:#122946;color:#d3e0f2;padding:24px 14px;z-index:5}.brand{display:flex;align-items:center;gap:11px;margin:0 6px 40px;color:white;font-weight:800;font-size:16px}.mark{background:#2c77cb;padding:11px;border-radius:12px}.brand small{font-weight:400;color:#aac0db;font-size:12px;display:block;margin-top:4px}.section{font-size:10px;letter-spacing:1.5px;color:#91a8c6;font-weight:800;margin:0 13px 12px}.nav{display:block;width:100%;text-align:left;background:transparent;border:0;color:#d5e1f1;padding:13px 14px;border-radius:9px;margin-bottom:5px}.nav.active,.nav:hover{background:#2a517f;color:white}.aside-note{position:absolute;bottom:23px;left:18px;right:18px;border-top:1px solid #35506e;padding-top:14px;color:#a9bdd6;font-size:11px;line-height:1.7}.main{margin-left:244px}.topbar{height:70px;background:white;border-bottom:1px solid #dfe7f1;display:flex;align-items:center;justify-content:space-between;padding:0 34px;font-weight:700}.topbar span{font-size:11px;color:#647a99;font-weight:500}.canvas{max-width:1140px;margin:0 auto;padding:34px 35px 70px}.eyebrow{font-size:10px;letter-spacing:1.8px;font-weight:800;color:#6c91bb;text-transform:uppercase}.headline{display:flex;justify-content:space-between;gap:16px;align-items:center;margin:4px 0 25px}h1{font-size:29px;margin:8px 0 4px;letter-spacing:-.8px}h2{font-size:17px;margin:0 0 6px}h3{font-size:14px;margin:0}p{color:#6a7d97;margin:0;line-height:1.65}.muted{color:#6c7e98}.card{background:white;border:1px solid #dce6f2;border-radius:13px;padding:22px;box-shadow:0 4px 14px #193b6007}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:15px;margin-bottom:19px}.stat{font-size:29px;font-weight:800;margin-top:8px}.kicker{color:#788aa1;font-size:12px}.btn{border:1px solid #d0dfee;border-radius:8px;background:white;color:#1b477c;padding:10px 15px;font-weight:700;font-size:12px}.btn:hover{background:#eff6ff}.btn.primary{color:white;background:#2870c5;border-color:#2870c5}.btn.primary:hover{background:#1d5fad}.btn.ghost{border:0;background:transparent}.flex{display:flex;align-items:center;gap:10px}.between{display:flex;justify-content:space-between;align-items:center;gap:12px}.stack{display:grid;gap:15px}.filters{display:grid;grid-template-columns:1fr 195px auto;gap:9px;margin:18px 0}.input,textarea,select{border:1px solid #cbd9e9;border-radius:8px;background:white;width:100%;padding:12px;color:#1b3453;outline-color:#5e99df}textarea{resize:vertical;min-height:94px}label{font-size:12px;font-weight:800;display:block;margin:0 0 7px}.field{margin-bottom:18px}.help{font-size:11px;color:#7186a0;margin-top:5px}.pill{display:inline-block;border-radius:30px;padding:7px 10px;font-size:11px;font-weight:700;background:#ecf2fa;color:#42648b}.pill.amber{background:#fff3d9;color:#996200}.pill.green{background:#e4f5ed;color:#187049}.pill.blue{background:#e7f0fc;color:#2e659e}.workrow{display:grid;grid-template-columns:minmax(0,1fr) 150px 90px;gap:10px;align-items:center;padding:15px 0;border-top:1px solid #eaf0f6}.workrow strong{display:block;font-size:13px;margin-bottom:5px}.mini{font-size:11px;color:#7a8fa8}.steps{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:0 0 18px}.step{background:#e6edf6;padding:14px 15px;border-radius:9px;font-size:12px;font-weight:800;color:#617993}.step.done{background:#e4f5eb;color:#197350}.step.current{background:#deebff;color:#2266b4}.notice{background:#edf4fe;color:#315d8c;padding:14px 17px;border-radius:9px;font-size:12px;line-height:1.6;margin-bottom:17px}.notice.warn{background:#fff3de;color:#87591c}.summary{background:#f0f5fb;border-radius:9px;padding:14px;margin:0 0 17px}.summary strong{display:block;margin-bottom:5px}.checks{display:grid;gap:12px;margin:15px 0}.checks label{display:flex;align-items:center;gap:9px;margin:0;cursor:pointer}.checks input{accent-color:#2870c5;width:16px;height:16px}.detail{border:1px solid #e2e9f2;border-radius:9px;padding:15px}.detail summary{font-weight:800;cursor:pointer}.detail .inside{margin-top:18px}.footer{display:flex;justify-content:flex-end;gap:9px;margin-top:20px}.tag{font-size:10px;color:#6885a7;font-weight:800;letter-spacing:1px}.checkline{padding:10px 12px;background:#f2f7fc;border-radius:9px;display:flex;align-items:center;gap:9px}.dot{width:9px;height:9px;background:#dca449;border-radius:50%;flex:none}.dot.ok{background:#2da675}.hidden{display:none!important}.alert{padding:14px;border:1px solid #edcd83;border-radius:9px;background:#fff9eb;color:#835a19;font-size:12px}.success{padding:35px;text-align:center}.success .tick{font-size:42px;color:#199162}.upload{border:1px dashed #a9bfdc;border-radius:9px;padding:17px;background:#f4f8fd}.empty{text-align:center;padding:28px;color:#72849b}.counter{font-size:12px;color:#68829b}.notification{display:flex;align-items:center;justify-content:space-between;border-top:1px solid #e6edf4;padding:15px 0;gap:12px}.notification strong{display:block;margin-bottom:5px}.noteNew{background:#fff1d8;color:#9a6800;padding:5px 8px;border-radius:30px;font-size:10px;font-weight:800}@media(max-width:850px){aside{width:190px}.main{margin-left:190px}.canvas{padding:25px 16px}.cards{grid-template-columns:1fr}.filters{grid-template-columns:1fr}.workrow{grid-template-columns:1fr;gap:8px}.topbar{padding:0 16px}.headline{flex-wrap:wrap}}@media(max-width:580px){aside{position:static;width:auto;min-height:auto;padding:10px}.brand{margin-bottom:10px}.aside-note,.section{display:none}.nav{display:inline-block;width:auto}.main{margin-left:0}.topbar{height:50px}.steps{gap:3px}.step{font-size:10px;padding:9px}.card{padding:15px}}
</style><style>.status-panel{border:1px solid #dbe5f1;background:#f8fbff;border-radius:10px;padding:17px;margin:18px 0}.status-panel h2{font-size:15px;margin-bottom:11px}.status-grid{display:grid;grid-template-columns:190px 1fr;gap:10px 15px;font-size:12px}.status-grid dt{color:#667e98}.status-grid dd{margin:0;font-weight:700}.status-panel .mini{line-height:1.7;margin-top:12px}@media(max-width:600px){.status-grid{grid-template-columns:1fr;gap:2px}.status-grid dd{margin-bottom:8px}}</style><style id="marketing-v2-logout-style">.account-actions{display:flex;align-items:center;gap:14px;justify-content:flex-end}.logout-form{margin:0}.logout-button{background:#fff;border:1px solid #cbd9e9;border-radius:8px;padding:9px 14px;color:#1b477c;font-weight:700;font-size:12px;white-space:nowrap}.logout-button:hover,.logout-button:focus-visible{background:#edf4fe;outline-color:#2870c5}@media(max-width:700px){.account-actions{gap:7px}.account-actions span{display:none}.logout-button{padding:8px}}</style>
</head><body>
<aside><div class="brand"><div class="mark">▦</div><div>Enterprise BPM<small>Marketing Workspace V2</small></div></div><div class="section">MENU MARKETING</div><button class="nav" data-page="dashboard">▦ &nbsp; Dashboard</button><button class="nav" data-page="new">＋ &nbsp; Permintaan Baru</button><button class="nav" data-page="jobs">▤ &nbsp; Pekerjaan Saya</button><button class="nav" data-page="notifications">♧ &nbsp; Notifikasi <span id="navCount">(2)</span></button><div class="aside-note">PROTOTYPE V2 · SIMULASI LOKAL<br>Draft tersimpan pada DB pengujian.<br>Persiapan Brief tersimpan; PROD-03, lampiran, dan pengiriman belum aktif.</div></aside>
<div class="main"><header class="topbar">Marketing / Workspace
<div class="account-actions"><span>DRAFT PROD-02 AKTIF · PERSIAPAN BRIEF TERSIMPAN (BUKAN PROD-03) &nbsp; ◉ {{ auth()->user()->name }}</span>
<form method="POST" action="{{ route('logout') }}" class="logout-form">@csrf<button type="submit" class="logout-button" aria-label="Keluar dari akun">↪ &nbsp; Logout</button></form></div>
</header><main class="canvas"><div id="content"></div></main></div>
<script>
'use strict';
const $=s=>document.querySelector(s);const escapeHTML=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let page='dashboard', filter='all', query='', selected=1, sent=false, noteRead={},newCreated=false;
let jobs=[{id:1,client:'PT Simulasi Pameran Nusantara',name:'Booth Pameran 6 × 3 Meter',needs:'Klien membutuhkan booth modern ukuran 6 × 3 meter untuk pameran produk, dengan backdrop branding, meja penerima tamu, dan area display.',concept:'Konsep modern minimalis berwarna navy dan putih. Dibutuhkan visualisasi 3D dan penentuan spesifikasi booth berdasarkan hasil desain.',status:'draft',designer:true,provisional:true,source:'Spesifikasi material masih berupa estimasi Marketing, menunggu konfirmasi tim Produksi.',fileNames:[]},{id:2,client:'PT Demo Indonesia',name:'Backdrop Event Perusahaan',needs:'Pembuatan backdrop untuk kegiatan perusahaan.',concept:'Backdrop dengan branding dan pencahayaan sesuai referensi.',status:'ready',designer:false,provisional:false,source:'',fileNames:[]},{id:3,client:'PT Contoh Nusantara',name:'Display Produk Retail',needs:'Display produk di area retail.',concept:'Modular display dengan ruang untuk identitas brand.',status:'progress',designer:false,provisional:false,source:'',fileNames:[]}];
const draftApi = @json(route('marketing.workspace.drafts.index'));
const csrfToken = @json(csrf_token());
const preparationApi = @json(url('/marketing/workspace/preparation'));
const draftUpdateUrl = @json(url('/marketing/workspace/drafts'));
const prod02OfficialEditBase = @json(url('/production/briefs'));
function draftTitle(j){return j.persisted&&(!j.name?.trim()||j.name==='Draft belum diberi nama')?'Draft belum diberi nama · #'+j.dbId:j.name;}
function draftIdentity(j){return j.persisted?'Draft #'+j.dbId:'';}
async function loadSavedDrafts(){
  try { const r=await fetch(draftApi,{headers:{'Accept':'application/json'},credentials:'same-origin'});
    if(!r.ok)throw new Error('HTTP '+r.status);
    const data=await r.json();
    jobs=jobs.filter(j=>!j.persisted).concat((data.drafts||[]).map(d=>({
      id:'db-'+d.id, dbId:d.id,persisted:true,client:d.client_name||'',name:d.project_name||'Draft belum diberi nama',
      needs:d.description||'',concept:'',status:'draft',designer:false,provisional:false,source:'',fileNames:[]
    })));
    render();
  } catch (err) { console.error('Tidak dapat mengambil Draft:',err); alert('Draft tersimpan tidak dapat dimuat. Periksa koneksi Laravel.'); }
}
let form={client:'',name:'',needs:'',concept:'',designer:false,provisional:false,source:'',fileNames:[]};
const statusLabel={draft:'Perlu dilengkapi',ready:'Siap dikirim',progress:'Dalam proses'},statusClass={draft:'amber',ready:'green',progress:'blue'};
function header(k,t,subtitle,action=''){return `<div class="eyebrow">${k}</div><div class="headline"><div><h1>${t}</h1><p>${subtitle}</p></div>${action}</div>`}
function count(s){return jobs.filter(j=>j.status===s).length}
function stepbar(n){return `<div class="steps">${['Terima','Lengkapi Brief','Periksa & Kirim'].map((x,i)=>`<div class="step ${i+1<n?'done':i+1===n?'current':''}">${i+1<n?'✓':i+1} &nbsp; ${x}</div>`).join('')}</div>`}
function render(){document.querySelectorAll('[data-page]').forEach(x=>x.classList.toggle('active',x.dataset.page===page||(page==='detail'&&x.dataset.page==='jobs')||(page==='brief'&&x.dataset.page==='jobs')||(page==='send'&&x.dataset.page==='jobs')));$('#navCount').textContent=`(${2-Object.values(noteRead).filter(Boolean).length})`;
let html='';if(page==='dashboard'){html=header('ENTERPRISE BPM / MARKETING','Dashboard Marketing','Semua permintaan dan pekerjaan dalam satu tempat.','<button class="btn primary" data-go="new">＋ Permintaan Baru</button>')+`<div class="cards">${[['draft','Perlu dilengkapi'],['ready','Siap dikirim'],['progress','Dalam proses']].map(([s,l])=>`<div class="card"><div class="kicker">${l}</div><div class="stat">${count(s)}</div></div>`).join('')}</div><div class="card"><div class="between"><h2>Pekerjaan yang memerlukan perhatian</h2><button class="btn" data-go="jobs">Lihat Semua</button></div>${jobs.filter(j=>j.status!=='progress').map(jobRow).join('')}</div>`}
if(page==='jobs'){const filtered=jobs.filter(j=>(filter==='all'||j.status===filter)&&(j.name+' '+j.client).toLowerCase().includes(query.toLowerCase()));html=header('MARKETING / PEKERJAAN','Pekerjaan Saya','Cari dan lanjutkan pekerjaan tanpa berpindah modul.','<button class="btn primary" data-go="new">＋ Permintaan Baru</button>')+`<div class="card"><div class="filters"><input id="search" class="input" placeholder="Cari nama pekerjaan atau klien..." value="${escapeHTML(query)}"/><select id="filter" class="input"><option value="all">Semua status</option><option value="draft" ${filter==='draft'?'selected':''}>Perlu dilengkapi</option><option value="ready" ${filter==='ready'?'selected':''}>Siap dikirim</option><option value="progress" ${filter==='progress'?'selected':''}>Dalam proses</option></select><button class="btn" id="applyFilter">Cari / Filter</button></div><div class="counter">${filtered.length} pekerjaan</div>${filtered.length?filtered.map(jobRow).join(''):'<div class="empty">Tidak ada pekerjaan yang cocok.</div>'}</div>`}
if(page==='new'){html=header('LANGKAH 1 / 3','Terima Permintaan','Cukup isi tiga informasi utama. Lampiran bersifat opsional.')+stepbar(1)+`<div class="card"><h2>Informasi dasar klien</h2><form id="newform"><div class="field"><label>Nama Klien *</label><input class="input" name="client" required value="${escapeHTML(form.client)}" placeholder="Nama perusahaan klien"/></div><div class="field"><label>Nama Pekerjaan *</label><input class="input" name="name" required value="${escapeHTML(form.name)}" placeholder="Contoh: Booth Pameran"/></div><div class="field"><label>Kebutuhan Klien *</label><textarea class="input" name="needs" required placeholder="Apa yang diminta klien?">${escapeHTML(form.needs)}</textarea></div><div class="upload"><label>Lampiran klien (opsional)</label><input type="file" id="files" multiple accept=".pdf,.png,.jpg,.jpeg,.doc,.docx"/><div class="help">Lampiran belum diunggah; hanya tiga field utama yang tersimpan sebagai Draft. Maks. 5 MB per file untuk preview.</div><div id="filesLabel" class="help">${form.fileNames.map(escapeHTML).join(', ')}</div></div><div class="footer"><button type="button" class="btn" data-go="dashboard">Batal</button><button class="btn primary" type="submit">Simpan & Lanjutkan →</button></div></form></div>`}
if(page==='detail'){let j=jobs.find(x=>x.id===selected);html=header('MARKETING / DETAIL PEKERJAAN',escapeHTML(draftTitle(j)),escapeHTML(j.client),`<span class="pill ${statusClass[j.status]}">${statusLabel[j.status]}</span>`)+`<div class="card"><h2>Ringkasan permintaan</h2><p>${escapeHTML(j.needs)}</p><div class="summary" style="margin-top:17px"><strong>Brief saat ini</strong>${escapeHTML(j.concept||'Belum ada tambahan brief.')}</div>${j.persisted?`<section class="status-panel" id="prod02StatusPanel" aria-live="polite"><h2>Status Permintaan Klien — PROD-02</h2><p class="mini">Memuat status resmi dari database pengujian...</p></section>`:""}<div class="between"><div class="mini">${j.persisted?'Draft #'+j.dbId+' · ':''}Informasi yang sudah dicatat tidak perlu ditulis ulang.</div><div class="flex">${j.persisted&&j.status==='draft'?'<button class="btn" data-go="edit">Edit Permintaan</button><button class="btn" data-official="'+j.dbId+'">Selesaikan PROD-02 ↗</button>':''}${j.persisted?'<a class="btn" href="/marketing/workspace/brief-mapping/'+encodeURIComponent(j.dbId)+'">Pratinjau PROD-03 ↗</a>':''}<button class="btn primary" data-go="brief">${j.status==='progress'?'Lihat Brief':'Lengkapi Brief →'}</button></div></div></div>`}
if(page==='edit'){let j=jobs.find(x=>x.id===selected);if(!j||!j.persisted||j.status!=='draft'){go('jobs');return}html=header('MARKETING / DRAFT #'+j.dbId,'Edit Permintaan','Perbaiki informasi permintaan yang masih berstatus Draft.')+`<div class="card"><form id="editdraftform"><div class="field"><label>Nama Klien *</label><input class="input" name="client" required maxlength="255" value="${escapeHTML(j.client)}"/></div><div class="field"><label>Nama Pekerjaan *</label><input class="input" name="name" required maxlength="255" value="${escapeHTML(j.name==='Draft belum diberi nama'?'':j.name)}"/></div><div class="field"><label>Kebutuhan Klien *</label><textarea class="input" name="needs" required maxlength="10000">${escapeHTML(j.needs)}</textarea></div><div class="footer"><button type="button" class="btn" data-go="detail">Batal</button><button type="submit" class="btn primary">Simpan Perubahan</button></div></form></div>`}
if(page==='brief'){let j=jobs.find(x=>x.id===selected);html=header('LANGKAH 2 / 3','Lengkapi Brief','Data permintaan klien telah digunakan kembali.')+stepbar(2)+`<div class="card"><div class="summary"><strong>${escapeHTML(draftTitle(j))}</strong>${escapeHTML(j.needs)}</div><form id="briefform"><div class="field"><label>Konsep & hasil yang diharapkan *</label><textarea class="input" name="concept" required>${escapeHTML(j.concept)}</textarea></div><div class="checks"><label><input type="checkbox" name="designer" ${j.designer?'checked':''}/> Perlu bantuan Designer</label><label><input type="checkbox" name="provisional" ${j.provisional?'checked':''}/> Ada data sementara (provisional)</label></div><div id="provisionalArea" class="field ${j.provisional?'':'hidden'}"><label>Bagian sementara dan sumber/dasar estimasi *</label><textarea name="source" class="input" placeholder="Sebutkan nilai/komponen yang masih sementara dan sumbernya">${escapeHTML(j.source)}</textarea><div class="help">Rincian provisional perlu dicatat agar dapat ditinjau pada tahap berikutnya.</div></div><details class="detail"><summary>Informasi tambahan (jika diperlukan)</summary><div class="inside"><div class="field"><label>Spesifikasi tambahan (opsional)</label><textarea class="input" name="specification" placeholder="Bila sudah diketahui...">${escapeHTML(j.specification||'')}</textarea></div><div class="field"><label>Estimasi durasi (opsional)</label><input class="input" name="duration" value="${escapeHTML(j.duration||'')}" placeholder="Contoh: 7 hari kerja"/></div></div></details><div class="footer"><button type="button" class="btn" data-go="detail">Kembali</button><button type="submit" class="btn primary">Periksa & Kirim →</button></div></form></div>`}
if(page==='send'){let j=jobs.find(x=>x.id===selected);let issues=[];if(!j.client||!j.name||!j.needs)issues.push('Informasi permintaan klien belum lengkap');if(!j.concept.trim())issues.push('Konsep dan hasil yang diharapkan belum diisi');if(j.provisional&&!j.source.trim())issues.push('Dasar informasi provisional belum dicantumkan');html=header('LANGKAH 3 / 3','Periksa & Kirim','Periksa kelengkapan sebelum melanjutkan proses.')+stepbar(3)+(sent?`<div class="card success"><div class="tick">✓</div><h2>Simulasi pengiriman selesai</h2><p>Tidak ada perubahan ke Laravel, status asli, atau database.</p><div class="footer" style="justify-content:center"><button class="btn primary" data-go="dashboard">Kembali ke Dashboard</button></div></div>`:`<div class="card"><h2>Ringkasan pekerjaan</h2><div class="summary"><strong>${escapeHTML(draftTitle(j))}</strong>${escapeHTML(j.client)}<p>${escapeHTML(j.concept)}</p></div><div class="checks"><div class="checkline"><span class="dot ok"></span> Informasi permintaan awal tersedia</div><div class="checkline"><span class="dot ${issues.length?'':'ok'}"></span> ${issues.length?'Masih ada informasi yang perlu dilengkapi':'Isian brief memenuhi syarat simulasi'}</div><div class="checkline"><span class="dot ok"></span> Designer: ${j.designer?'Diperlukan':'Tidak diperlukan'}</div><div class="checkline"><span class="dot ok"></span> Provisional: ${j.provisional?'Ada, dasar informasi tercatat':'Tidak ada'}</div></div>${issues.length?`<div class="alert"><strong>Perlu dilengkapi</strong><ul>${issues.map(i=>`<li>${escapeHTML(i)}</li>`).join('')}</ul></div>`:`<div class="notice">Pemeriksaan ini hanya simulasi UI. Pengiriman sesungguhnya tetap harus mengikuti validasi, approval, dan distribusi pada workflow FINAL/LOCKED.</div>`}<div class="footer"><button class="btn" data-go="brief">Perbaiki Brief</button><button class="btn primary" id="simulateSend" ${issues.length?'disabled':''}>Simulasikan Pengiriman</button></div></div>`)}
if(page==='notifications'){html=header('MARKETING / INFORMASI','Notifikasi','Pembaruan penting yang memerlukan perhatian.')+`<div class="card"><h2>Notifikasi Marketing</h2>${[{title:'Brief Booth Pameran perlu dilengkapi',desc:'Lengkapi data sebelum pemeriksaan kesiapan.',id:0,job:1},{title:'Backdrop Event siap diproses',desc:'Periksa ringkasan sebelum melanjutkan.',id:1,job:2}].map(x=>`<div class="notification"><div><strong>${x.title} ${!noteRead[x.id]?'<span class="noteNew">BARU</span>':''}</strong><p>${x.desc}</p></div><button class="btn" data-note="${x.id}" data-job="${x.job}">Buka</button></div>`).join('')}</div>`}
$('#content').innerHTML=html;
}
function jobRow(j){return `<div class="workrow"><div><strong>${escapeHTML(draftTitle(j))}</strong><span class="mini">${escapeHTML(j.client)} ${j.persisted?`· Draft #${j.dbId}`:""}</span></div><div><span class="pill ${statusClass[j.status]}">${statusLabel[j.status]}</span></div><button class="btn" data-open="${j.id}">Buka →</button></div>`}
function go(next){page=next;render();window.scrollTo(0,0);if(next==='brief')loadPreparationForSelected();}
document.addEventListener('click', function(e) {
  const button = e.target.closest('[data-official]');
  if (!button) return;
  const id = Number(button.dataset.official);
  const job = jobs.find(j => j.persisted && Number(j.dbId) === id && j.status === 'draft');
  if (!Number.isSafeInteger(id) || id < 1 || !job) return;
  window.location.assign(prod02OfficialEditBase + '/' + id + '/edit');
});
document.addEventListener('click',e=>{let el=e.target.closest('[data-page],[data-go],[data-open],[data-note],#simulateSend,#applyFilter');if(!el)return;if(el.dataset.open){selected=el.dataset.open.startsWith("db-")?el.dataset.open:Number(el.dataset.open);go('detail')}else if(el.dataset.note!==undefined){noteRead[el.dataset.note]=true;selected=Number(el.dataset.job);go('detail')}else if(el.id==='simulateSend'){sent=true;go('send')}else if(el.id==='applyFilter'){query=$('#search').value;filter=$('#filter').value;render()}else if(el.dataset.page){go(el.dataset.page)}else if(el.dataset.go){if(el.dataset.go==='new')form={client:'',name:'',needs:'',concept:'',designer:false,provisional:false,source:'',fileNames:[]};go(el.dataset.go)}});
document.addEventListener('change',e=>{if(e.target.id==='files'){const files=[...e.target.files];if(files.some(f=>f.size>5*1024*1024)){alert('Simulasi membatasi file ke 5 MB per berkas.');e.target.value='';return}form.fileNames=files.map(f=>f.name);$('#filesLabel').textContent=form.fileNames.join(', ')||'Belum ada file dipilih'}if(e.target.name==='provisional')$('#provisionalArea').classList.toggle('hidden',!e.target.checked)});
document.addEventListener('submit',e=>{if(e.target.id==='newform'){e.preventDefault();const d=new FormData(e.target);form.client=String(d.get('client')||'').trim();form.name=String(d.get('name')||'').trim();form.needs=String(d.get('needs')||'').trim();let id=Math.max(...jobs.map(j=>j.id))+1;jobs.unshift({id,client:form.client,name:form.name,needs:form.needs,concept:'',status:'draft',designer:false,provisional:false,source:'',fileNames:[...form.fileNames]});selected=id;sent=false;newCreated=true;go('brief')}else if(e.target.id==='briefform'){e.preventDefault();let j=jobs.find(j=>j.id===selected);const d=new FormData(e.target);j.concept=String(d.get('concept')||'').trim();j.designer=d.has('designer');j.provisional=d.has('provisional');j.source=j.provisional?String(d.get('source')||'').trim():'';sent=false;go('send')}});
document.addEventListener('submit',async function(e){
 if(e.target.id!=='newform')return;
 e.preventDefault();e.stopImmediatePropagation();
 const d=new FormData(e.target); const client=String(d.get('client')||'').trim();
 const name=String(d.get('name')||'').trim();const needs=String(d.get('needs')||'').trim();
 const btn=e.target.querySelector('[type="submit"]');btn.disabled=true;
 try{const r=await fetch(draftApi,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':csrfToken},body:JSON.stringify({client,name,needs})});
  if(!r.ok){const issue=await r.json().catch(()=>({}));throw new Error(issue.message||'HTTP '+r.status)}
  const result=await r.json();const saved=result.draft;
  const job={id:'db-'+saved.id,dbId:saved.id,persisted:true,client:saved.client_name,name:saved.project_name,needs:saved.description,concept:'',status:'draft',designer:false,provisional:false,source:'',fileNames:[]};
  jobs.unshift(job);selected=job.id;sent=false;go('brief');
  alert('Draft PROD-02 #'+saved.id+' telah tersimpan di database pengujian. Bagian Lengkapi Brief masih simulasi dan belum disimpan.');
 }catch(err){alert('Draft tidak tersimpan: '+err.message)}finally{btn.disabled=false}
},true);
document.addEventListener('submit',async function(e){
 if(e.target.id!=='editdraftform')return;
 e.preventDefault();e.stopImmediatePropagation();
 const j=jobs.find(x=>x.id===selected);if(!j||!j.persisted||j.status!=='draft')return;
 const d=new FormData(e.target), btn=e.target.querySelector('[type="submit"]');
 btn.disabled=true;
 try{
   const r=await fetch(draftUpdateUrl+'/'+encodeURIComponent(j.dbId),{method:'PUT',credentials:'same-origin',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':csrfToken},body:JSON.stringify({client:String(d.get('client')||'').trim(),name:String(d.get('name')||'').trim(),needs:String(d.get('needs')||'').trim()})});
   if(!r.ok){const issue=await r.json().catch(()=>({}));throw new Error(issue.message||'HTTP '+r.status)}
   const result=await r.json(),saved=result.draft;
   j.client=saved.client_name;j.name=saved.project_name;j.needs=saved.description;
   go('detail');alert('Perubahan Draft #'+j.dbId+' berhasil disimpan.');
 }catch(err){alert('Perubahan gagal: '+err.message)}finally{btn.disabled=false}
},true);

async function loadPreparationForSelected(){
 const j=jobs.find(x=>x.id===selected); if(!j||!j.persisted)return;
 const id=j.id;
 try{
  const r=await fetch(preparationApi+'/'+encodeURIComponent(j.dbId),{credentials:'same-origin',headers:{'Accept':'application/json'}});
  if(!r.ok)throw new Error('HTTP '+r.status);
  const p=(await r.json()).preparation||{};
  if(selected!==id)return;
  Object.assign(j,{concept:p.concept||'',designer:!!p.designer,provisional:!!p.provisional,source:p.source||'',specification:p.specification||'',duration:p.duration||''});
  if(page==='brief')render();
 }catch(err){alert('Gagal mengambil persiapan Brief: '+err.message)}
}
document.addEventListener('submit', async function(e){
 if(e.target.id!=='briefform')return;
 const j=jobs.find(x=>x.id===selected);if(!j||!j.persisted)return;
 e.preventDefault();e.stopImmediatePropagation();
 const d=new FormData(e.target),btn=e.target.querySelector('[type="submit"]');btn.disabled=true;
 const payload={concept:String(d.get('concept')||'').trim(),designer:d.has('designer'),provisional:d.has('provisional'),source:d.has('provisional')?String(d.get('source')||'').trim():'',specification:String(d.get('specification')||'').trim(),duration:String(d.get('duration')||'').trim()};
 if(payload.provisional&&!payload.source){alert('Isi dasar informasi provisional.');btn.disabled=false;return}
 try{
  const r=await fetch(preparationApi+'/'+encodeURIComponent(j.dbId),{method:'PUT',credentials:'same-origin',headers:{'Accept':'application/json','Content-Type':'application/json','X-CSRF-TOKEN':csrfToken},body:JSON.stringify(payload)});
  if(!r.ok){const x=await r.json().catch(()=>({}));throw new Error(x.message||'HTTP '+r.status)}
  Object.assign(j,payload);sent=false;go('send');
  alert('Persiapan Brief tersimpan untuk Draft #'+j.dbId+'. Ini BELUM menjadi Brief Marketing PROD-03 dan tidak dikirim.');
 }catch(err){alert('Persiapan Brief gagal disimpan: '+err.message)}finally{btn.disabled=false}
},true);

const prod02StatusBase = @json(url('/marketing/workspace/prod02-status'));
const prod03CreateBase = @json(url('/production/marketing-briefs/from-client-brief'));
const prod03ShowBase = @json(url('/production/marketing-briefs'));
let prod02DetailSequence=0;
async function loadProd02StatusForSelected(){
 const j=jobs.find(x=>x.id===selected);
 if(!j||!j.persisted||page!=='detail')return;
 const panel=document.getElementById('prod02StatusPanel');if(!panel)return;
 const seq=++prod02DetailSequence;
 try{
  const r=await fetch(prod02StatusBase+'/'+encodeURIComponent(j.dbId),{credentials:'same-origin',headers:{'Accept':'application/json'}});
  if(!r.ok)throw Error('HTTP '+r.status);
  const d=await r.json();
  if(seq!==prod02DetailSequence||selected!==j.id||page!=='detail'||!panel.isConnected)return;
  const label=d.status==='DRAFT'?'Draft':d.status==='RECORDED'?'Tercatat resmi':d.status;
  const indicators=(d.missing_basic||[]).length?'Belum lengkap: '+d.missing_basic.join(', '):'Data inti terisi';
  panel.innerHTML='<h2>Status Permintaan Klien — PROD-02</h2><dl class="status-grid">'+
   '<dt>Status dokumen</dt><dd>'+escapeHTML(label)+'</dd>'+
   '<dt>Nomor REQ</dt><dd>'+escapeHTML(d.request_number||'Belum diterbitkan')+'</dd>'+
   '<dt>Data inti PROD-02</dt><dd>'+escapeHTML(indicators)+'</dd>'+
   '</dl><p class="mini">Indikator data inti bersifat informatif, bukan keputusan siap Submit. Pemeriksaan duplikasi, ketentuan lampiran, dan kelayakan pencatatan tetap dilakukan di formulir resmi PROD-02.</p>';
  // Tahap 2E: navigasi saja; proses pembuatan tetap melalui controller resmi PROD-03.
  const existingBrief=d.existing_marketing_brief_id;
  let bridge='';
  if(d.status==='RECORDED' && existingBrief){
    bridge='<a class="btn primary" href="'+prod03ShowBase+'/'+encodeURIComponent(existingBrief)+'">Buka Brief Marketing PROD-03 ↗</a>';
  } else if(d.status==='RECORDED'){
    bridge='<a class="btn primary" href="'+prod03CreateBase+'/'+encodeURIComponent(j.dbId)+'/create">Buat Brief Marketing PROD-03 ↗</a>';
  } else {
    bridge='<span class="mini">Brief Marketing resmi baru dapat dibuat setelah permintaan tercatat (RECORDED) melalui PROD-02.</span>';
  }
  panel.insertAdjacentHTML('beforeend','<div class="between" style="margin-top:16px;gap:10px;align-items:center">'+bridge+'</div>');
 }catch(error){if(seq===prod02DetailSequence&&panel.isConnected){panel.innerHTML='<h2>Status Permintaan Klien — PROD-02</h2><p class="mini">Status belum dapat dimuat ('+escapeHTML(error.message)+'). Silakan buka PROD-02 resmi untuk memeriksa.</p>'}}
}
// Pembaruan status hanya saat Detail Draft dibuka; tidak ada perubahan database.
const originalGo2D=go;
go=function(next){originalGo2D(next);if(next==='detail')loadProd02StatusForSelected();};

render();
loadSavedDrafts();
</script></body></html>
